import fs from "node:fs";

/*
 * The owner sidebar is now generated by apply-owner-sidebar-lag-fix.mjs using the
 * non-destructive V26 loader. This final step intentionally does not rewrite the
 * loader again; doing so previously reintroduced the sidebar disappearance bug.
 */
const ownerPath="owner-modules-loader.jsx";
if(!fs.existsSync(ownerPath))throw new Error("owner-modules-loader.jsx is missing; build stopped safely.");
const text=fs.readFileSync(ownerPath,"utf8");
if(!text.includes("SMALLBIZ_OWNER_MODULES_LOADER_V26_SAFE")){
  throw new Error("Unsafe/old owner loader detected; final Growth/Cashier rewrite is disabled to prevent sidebar regression.");
}
console.log("Skipped legacy Growth/Cashier loader rewrite: V26 safe owner loader remains authoritative.");
